    # 0: source, 1: sink, 2..(n+1): vertices, (n+2)..(n+m+1): edges
    S = 0
    T = 1
    num_vertices = n + 2 + m
    dinic = Dinic(num_vertices)

    # From source to each edge node (capacity = edge weight)
    for j, (v, u, w) in enumerate(edges):
        edge_node = 2 + n + j
        dinic.add_edge(S, edge_node, w)

