        for clause in clauses:
            all_false = True
            for lit in clause:
                var = abs(lit) - 1
                val = assignment[var] == 1 if lit > 0 else assignment[var] == 0
                if val:
                    all_false = False
                    break
            if all_false:
                return False
        return True

    # Backtrack - try each unassigned variable
    changed = [False] * m

    def backtrack(idx):
        if check():
            return True
        # Try to fix unsatisfied clause
        for i in range(n):
            clause = clauses[i]
            all_false = True
            for lit in clause:
                var = abs(lit) - 1
                val = assignment[var] == 1 if lit > 0 else assignment[var] == 0
