        lazy[2 * node] += lazy[node];
        tree[2 * node + 1] += lazy[node];
        lazy[2 * node + 1] += lazy[node];
        lazy[node] = 0;
    }
}

void update(int l, int r, int node, int lhs, int rhs, long long val) {
    if (rhs < l || r < lhs) return;
    if (l <= lhs && rhs <= r) {
        tree[node] += val * (rhs - lhs + 1);
        lazy[node] += val;
        return;
    }
    push(node);
    int mid = (lhs + rhs) / 2;
    update(l, r, 2 * node, lhs, mid, val);
    update(l, r, 2 * node + 1, mid + 1, rhs, val);
}

long long query(int l, int r, int node, int lhs, int rhs) {
    if (rhs < l || r < lhs) return 0;
    if (l <= lhs && rhs <= r) return tree[node];
    push(node);
    int mid = (lhs + rhs) / 2;
    return max(query(l, r, 2 * node, lhs, mid), query(l, r, 2 * node + 1, mid + 1, rhs));
}

