                        continue

                    valid = True

                    # All border cells must be 1
                    for k in range(s):
                        if grid[r][c + k] != 1 or grid[r + s - 1][c + k] != 1 or \
                           grid[r + k][c] != 1 or grid[r + k][c + s - 1] != 1:
                            valid = False
                            break

                    if not valid:
                        continue

                    # Interior must be 0 (for s >= 3)
                    if s >= 3:
                        for rr in range(r + 1, r + s - 1):
                            for cc in range(c + 1, c + s - 1):
                                if grid[rr][cc] != 0:
                                    valid = False
                                    break
                            if not valid:
                                break

                    if not valid:
                        continue

                    # No foreign 1s touch (check 8 neighbors)
                    for rr in range(r - 1, r + s):
                        for cc in range(c - 1, c + s):
                            inside = r <= rr < r + s and c <= cc < c + s
                            if inside:
                                continue
                            if 0 <= rr < n and 0 <= cc < m and grid[rr][cc] == 1:
                                valid = False
                                break
                        if not valid:
                            break

                    if valid:
                        count += 1

        # Check diagonal (diamond) squares
        for r in range(n):
            for c in range(m):
                max_k = min(r, c, n - 1 - r, m - 1 - c) + 1
                if max_k < 2:
                    continue

                for k in range(2, max_k + 1):
                    valid = True

                    # All boundary cells (Manhattan distance k-1) must be 1
                    for i in range(-k + 1, k):
                        for j in range(-k + 1, k):
                            if abs(i) + abs(j) == k - 1:
                                if grid[r + i][c + j] != 1:
                                    valid = False
                                    break
                        if not valid:
                            break

                    if not valid:
                        continue

                    # Interior (Manhattan distance < k-1, excluding center) must be 0
                    for i in range(-k + 1, k):
                        for j in range(-k + 1, k):
                            if i == 0 and j == 0:
                                continue
                            if abs(i) + abs(j) < k - 1:
                                if grid[r + i][c + j] != 0:
                                    valid = False
                                    break
                        if not valid:
                            break

                    if not valid:
                        continue

                    # No foreign 1s touch from outside
                    for i in range(-k, k + 1):
                        for j in range(-k, k + 1):
                            md = abs(i) + abs(j)
                            if md <= k - 1:
                                continue
                            if 0 <= r + i < n and 0 <= c + j < m and grid[r + i][c + j] == 1:
                                valid = False
                                break
                        if not valid:
                            break

                    if valid:
                        count += 1

        results.append(str(count))

    return '\n'.join(results)
