```python
def solution(data):
    import sys
    import os
    lines = data.strip().split('\n')

    n = int(lines[0])
    x1, y1, x2, y2 = map(int, lines[1].split())

    # Parse mice
    mice = []
    for i in range(2, 2 + n):
        parts = lines[i].split()
        rix, ri_y, vix, viy = int(parts[0]), int(parts[1]), int(parts[2]), int(parts[3])
        mice.append((rix, ri_y, vix, viy))

    x1, x2 = float(x1), float(x2)
    y1, y2 = float(y1), float(y2)

    # Global valid interval [min_t, max_t], starting as [0, ∞)
    min_t = 0.0
    max_t = float('inf')

    for rix, ri_y, vix, viy in mice:
        # X interval for this mouse
        if vix == 0:
            if not (x1 < rix < x2):
                min_t = max(min_t, float('inf'))  # Invalid
                max_t = min(max_t, -float('inf'))
                break
            else:
                interval_x = (-float('inf'), float('inf'))
        else:
            t_in_x = (x1 - rix) / vix
            t_out_x = (x2 - rix) / vix
            if vix > 0:
                interval_x = (t_in_x, t_out_x)
            else:  # vix < 0, intervals swapped
                interval_x = (t_out_x, t_in_x)

        # Y interval for this mouse
        if viy == 0:
            if not (y1 < ri_y < y2):
                min_t = max(min_t, float('inf'))
                max_t = min(max_t, -float('inf'))
                break
            else:
                interval_y = (-float('inf'), float('inf'))
        else:
            t_in_y = (y1 - ri_y) / viy
            t_out_y = (y2 - ri_y) / viy
            if viy > 0:
                interval_y = (t_in_y, t_out_y)
            else:  # viy < 0, intervals swapped
                interval_y = (t_out_y, t_in_y)

        # Combine X and Y intervals
        t_in = max(interval_x[0], interval_y[0])
        t_out = min(interval_x[1], interval_y[1])

        # Intersect with global interval [min_t, max_t]
        new_min = max(min_t, t_in)
        new_max = min(max_t, t_out)

        # Check if interval is valid
        if new_min >= new_max:
            min_t = max(min_t, float('inf'))
            max_t = min(max_t, -float('inf'))
            break

        # Update global interval
        min_t = new_min
        max_t = new_max

    if max_t <= min_t:
        return "-1"
    else:
        return f"{min_t:.10f}"


