def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ""

    t = int(lines[0])
    idx = 1
    output_lines = []

    for _ in range(t):
        if idx >= len(lines):
            break
        n = int(lines[idx])
        idx += 1

        if n == 0:
            output_lines.append("0")
            continue

        wires = []
        contact_wires = {}

        for i in range(n):
            if idx >= len(lines):
                break
            parts = lines[idx].split()
            idx += 1
            x, y = int(parts[0]), int(parts[1])
            wires.append((x, y))

            if x not in contact_wires:
                contact_wires[x] = []
            contact_wires[x].append(i)

            if y not in contact_wires:
                contact_wires[y] = []
            contact_wires[y].append(i)

        parent = list(range(n))

        def find(i):
            while parent[i] != i:
                parent[i] = parent[parent[i]]
                i = parent[i]
            return i

        def union(i, j):
            pi, pj = find(i), find(j)
            if pi != pj:
                parent[pi] = pj

        # Union wires that share contact points
        for c in contact_wires:
            wires_list = contact_wires[c]
            for i in range(1, len(wires_list)):
                union(wires_list[0], wires_list[i])

        # Find unique components
        roots = set(find(i) for i in range(n))
        num_components = len(roots)

        # Minimum operations to connect all components
        output_lines.append(str(num_components - 1))

        if num_components > 1:
            # Find one representative wire per component
            comp_to_rep = {}
            for i in range(n):
                root = find(i)
                if root not in comp_to_rep:
                    comp_to_rep[root] = i

            # Sort representatives to get a consistent order
            reps = sorted(comp_to_rep.values())

            # Connect consecutive components
            new_contact = 10**9 + 1

            for i in range(len(reps) - 1):
                w = reps[i + 1]
                a, b = wires[w]

                # Weld one endpoint of wire to new_contact
                # This connects this component to the previous one
                output_lines.append(f"{w + 1} {a} {new_contact}")

    return '\n'.join(output_lines)
