def solution(input_string):
    lines = input_string.strip().split('\n')
    n, a, b = map(int, lines[0].split())
    a_list = list(map(int, lines[1].split()))

    if n == 0:
        return '0'

    if n == 1:
        # Single element - cannot remove entire array
        return '0'

    # Find all prime factors
    prime_factors = set()
    for x in a_list:
        temp = x
        d = 2
        while d * d <= temp:
            if temp % d == 0:
                prime_factors.add(d)
                while temp % d == 0:
                    temp //= d
            d += 1
        if temp > 1:
            prime_factors.add(temp)

    if not prime_factors:
        # Default to checking 2
        prime_factors = {2}

    min_cost = float('inf')

    for g in prime_factors:
        first_bad = -1
        last_bad = -1
        change_count = 0

        for i in range(n):
            x = a_list[i]
            is_divisible = (x % g == 0)
            can_change = ((x - 1) % g == 0) or ((x + 1) % g == 0)

            if is_divisible:
                continue
            elif can_change:
                change_count += 1
            else:
                if first_bad == -1:
                    first_bad = i
                last_bad = i

        # Option 1: No removal needed (all elements can be fixed or are good)
        if first_bad == -1:
            cost = change_count * b
            min_cost = min(min_cost, cost)
            continue

        # Option 2: Must remove subsegment from first_bad to last_bad
        # Calculate minimum cost by potentially extending removal

        # Initial cost
        base_length = last_bad - first_bad + 1
        cost = base_length * a + change_count * b

        # Try extending removal to the left
        temp_first = 0
        temp_last = last_bad
        temp_change = change_count

        for i in range(first_bad):
            if a < b:
                temp_first = i
                temp_last = last_bad
                temp_change -= 1
                cost = (temp_last - temp_first + 1) * a + temp_change * b

        # Try extending removal to the right
        temp_first = first_bad
        temp_last = n - 1
        temp_change = change_count

        for i in range(last_bad + 1, n):
            if a < b:
                temp_first = first_bad
                temp_last = i
                temp_change -= 1
                cost = (temp_last - temp_first + 1) * a + temp_change * b

        min_cost = min(min_cost, cost)

    return str(max(0, min_cost))

