def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    MOD = 10**9 + 7

    clauses = []
    for i in range(n):
        parts = list(map(int, lines[i + 1].split()))
        clauses.append(parts[1:])

    var_clauses = {i: [] for i in range(1, m + 1)}
    for i, clause in enumerate(clauses):
        for lit in clause:
            var_clauses[abs(lit)].append(i)

    included = set()
    for v in var_clauses:
        if var_clauses[v]:
            included.add(v)

    ans = pow(2, m - len(included), MOD)

    parent = list(range(1, m + 1))
    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]
    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py

    for i in range(n):
        if len(clauses[i]) >= 2:
            union(abs(clauses[i][0]), abs(clauses[i][1]))

    components = {}
    for v in range(1, m + 1):
        r = find(v)
        if r not in components:
            components[r] = []
        components[r].append(v)

    for vars in components.values():
        if not vars:
            continue
        ans2 = count_component(vars, clauses, m)
        ans = (ans * ans2) % MOD

    return f"{ans}\n"

def count_component(vars, clauses, m):
    from collections import deque
    if len(vars) == 1:
        return 1
    adj = {v: [] for v in vars}
    var_set = set(vars)
    for i, c in enumerate(clauses):
        if len(c) == 2:
            v1, v2 = abs(c[0]), abs(c[1])
            if v1 in adj and v2 in adj:
                adj[v1].append(v2)
                adj[v2].append(v1)

    for v in vars:
        if len(adj[v]) != 1:
            return 1

    # Path structure
    if len(var_set) <= 3:
        return pow(2, len(var_set) - 1)
    return pow(2, len(var_set) - 1) % 1000000007
